using System;

namespace SodRpg.Core.Game
{
    public static partial class BossProfiles
    {
        public const string SeekerSetId = "set.boss_seeker";
        public const string SeekerRewardId = "boss_seeker.soul_prison";
        public const string SeekerNativeContract = "exact-DeathInterrupt-callback-and-quality-native-heal;final-native-heal-plus-min10percent-.20H;one-native-dispatch;preserve-discarded-native-infinite-shield-HP1-consumption-invulnerability;overflow-self25percent-cap.30H-6s-ally25percent-cap.40H-3s-nearest-alive-allied-hero6m-excluding-self;confirmed-native-consumption-retains-finite-shields;manual-reduction-death-room-clears;actor-parent-gem-skill-pool-life-room-run-gear-guards";
        public const string SeekerEventOrder = "E1-advance-green-purple-red-once-even-during-CD;phase-shot-CD3;existing-stage3-double-copies-current-phase-once-then-disappears;parts;E3-departure-only-shared-single-nonEntity-double;E2-fixed-claw-fan-three-pulses-and-once-shield";
        private static BossChannelDef SeekerChannel(string id,int value,int cap,BossCoefficientKind kind=BossCoefficientKind.Damage) => new BossChannelDef(id,value*1000,cap*1000,kind);
        private static BossMoveProfile SeekerProfile(string id,string ja,string en, string zh,BossChannelDef[] channels,params BossAction[] actions) => new BossMoveProfile("boss_seeker."+id,SeekerSetId,new Txt(ja,en,zh),channels,actions);
        private static BossAction SeekerOrb(BossEvent kind,string channel,int cd,int life=BossSeekerBalance.OrbDefaultLifetimeMillis,int speed=BossSeekerBalance.OrbDefaultSpeedMilli) => new BossAction(kind,BossMechanism.Projectile,BossPayload.Damage,channel,BossShape.Circle,BossAnchor.Hit,cooldownMillis:cd,lifetimeMillis:life,maxInstances:BossSeekerBalance.OrbMaxInstances,radiusMilli:BossSeekerBalance.OrbRadiusMilli,rangeMilli:BossSeekerBalance.OrbRangeMilli,widthMilli:BossSeekerBalance.OrbWidthMilli,speedMilli:speed,firstHitOnly:true);
        internal static BossMoveProfile[] CreateSeekerMoves() => new[]
        {
            SeekerProfile("weapon","通常攻撃が命中したとき、主対象の位置へ球を1発発射する。球の射程は8m、持続は1秒で、到達すると半径1.5mの爆発を起こし、攻撃力・魔力の高い方の18%（上限54%）のダメージを与える。壁に衝突しても爆発しない。再発動まで3秒かかる。","When your basic attack hits, fire 1 orb at the main target's position. The orb has an 8m range and lasts 1 second. On arrival, it explodes in a 1.5m radius, dealing damage equal to 18% of whichever is higher: your Attack or Ability Power (cap: 54%). It does not explode on contact with a wall. Cooldown: 3 seconds.", "通常攻击命中时，向主要目标位置发射1颗球。球的射程8m，持续1秒，到达时引发半径1.5m的爆炸，造成相当于攻击力与法术强度中较高一方18%（上限54%）的伤害。撞墙不会爆炸。冷却3秒。",new[]{SeekerChannel("SeekerOrb",BossSeekerBalance.SeekerOrbValue,BossSeekerBalance.SeekerOrbCap)},SeekerOrb(BossEvent.MainHit,"SeekerOrb",BossSeekerBalance.WeaponA0CooldownMillis)),
            SeekerProfile("armor","ダメージを受けたとき、自身の位置に分身を1体、2秒間出現させ、自身は攻撃力・魔力の高い方の18%（上限54%）の障壁を2秒間得る。分身は3部位効果の分身と合わせて同時に最大1体まで存在でき、挑発や敵の標的変更の効果はない。再発動まで10秒かかる。","When you take damage, create a double at your position for 2 seconds and gain a shield equal to 18% of whichever is higher: your Attack or Ability Power (cap: 54%), for 2 seconds. Only 1 double can exist at a time, including the 3-piece effect's double. Doubles do not taunt enemies or change their targets. Cooldown: 10 seconds.", "受到伤害时，在自身位置生成1个分身，持续2秒，并获得相当于攻击力与法术强度中较高一方18%（上限54%）的护盾，持续2秒。与3件套效果的分身合计同时最多存在1个。分身不会嘲讽敌人或改变其目标。冷却10秒。",new[]{SeekerChannel("SeekerDoubleGuard",BossSeekerBalance.SeekerDoubleGuardValue,BossSeekerBalance.SeekerDoubleGuardCap,BossCoefficientKind.Shield)},new BossAction(BossEvent.NativeDamageTaken,BossMechanism.Defense,BossPayload.Shield,"SeekerDoubleGuard",cooldownMillis:BossSeekerBalance.ArmorA0CooldownMillis,lifetimeMillis:BossSeekerBalance.ArmorA0LifetimeMillis,maxInstances:BossSeekerBalance.ArmorA0MaxInstances)),
            SeekerProfile("charm","記憶を使ったとき、8m以内の最も近い敵へ誘導弾を1発放つ。誘導弾の持続は2秒、最大移動距離は8mで、命中したとき、または消えるときに、半径1.5mの範囲へ攻撃力・魔力の高い方の24%（上限72%）のダメージを与える。再発動まで6秒かかる。","When you use a memory, fire 1 homing projectile at the nearest enemy within 8m. It lasts 2 seconds and travels at most 8m. On hit or when it disappears, deal damage equal to 24% of whichever is higher: your Attack or Ability Power (cap: 72%), in a 1.5m radius. Cooldown: 6 seconds.", "使用记忆时，向8m以内最近的敌人发射1枚追踪弹。追踪弹持续2秒，最多移动8m，命中或消失时对半径1.5m范围造成相当于攻击力与法术强度中较高一方24%（上限72%）的伤害。冷却6秒。",new[]{SeekerChannel("SeekerChaser",BossSeekerBalance.SeekerChaserValue,BossSeekerBalance.SeekerChaserCap)},SeekerOrb(BossEvent.MemoryUse,"SeekerChaser",BossSeekerBalance.CharmA0CooldownMillis,BossSeekerBalance.CharmA0LifetimeMillis,BossSeekerBalance.CharmA0SpeedMilli)),
            SeekerProfile("head","通常攻撃が命中したとき、8m以内の対象地点に予告を出し、0.4秒後に半径2mの範囲へ攻撃力・魔力の高い方の20%（上限60%）のダメージを与える。再発動まで5秒かかり、画面は暗転しない。","When your basic attack hits, mark the target point within 8m. After a 0.4-second warning, deal damage equal to 20% of whichever is higher: your Attack or Ability Power (cap: 60%), in a 2m radius. The screen does not darken. Cooldown: 5 seconds.", "通常攻击命中时，在8m以内的目标地点显示预警，0.4秒后对半径2m范围造成相当于攻击力与法术强度中较高一方20%（上限60%）的伤害。画面不会变暗。冷却5秒。",new[]{SeekerChannel("SeekerAim",BossSeekerBalance.SeekerAimValue,BossSeekerBalance.SeekerAimCap)},new BossAction(BossEvent.MainHit,BossMechanism.Field,BossPayload.Damage,"SeekerAim",BossShape.Circle,BossAnchor.Hit,cooldownMillis:BossSeekerBalance.HeadA0CooldownMillis,delayMillis:BossSeekerBalance.HeadA0DelayMillis,maxInstances:BossSeekerBalance.HeadA0MaxInstances,radiusMilli:BossSeekerBalance.HeadA0RadiusMilli,rangeMilli:BossSeekerBalance.HeadA0RangeMilli)),
            SeekerProfile("hands","記憶を使ったとき、8m以内の最も近い敵の位置に、2秒間持続する半径2mの紫の領域を生成する。領域は敵を追わず、子領域も生成しない。領域は0.5秒後と1.5秒後に、それぞれ攻撃力・魔力の高い方の10%（上限30%）のダメージを与える。再発動まで6秒かかる。","When you use a memory, create a purple field with a 2m radius at the nearest enemy's position within 8m. The field lasts 2 seconds, does not follow the enemy, and does not create additional fields. After 0.5 and 1.5 seconds, it deals damage equal to 10% of whichever is higher: your Attack or Ability Power (cap: 30%), each time. Cooldown: 6 seconds.", "使用记忆时，在8m以内最近敌人的位置生成半径2m的紫色领域，持续2秒。领域不会追踪敌人，也不会生成额外领域。分别在0.5秒后和1.5秒后造成相当于攻击力与法术强度中较高一方10%（上限30%）的伤害。冷却6秒。",new[]{SeekerChannel("SeekerPurple",BossSeekerBalance.SeekerPurpleValue,BossSeekerBalance.SeekerPurpleCap)},new BossAction(BossEvent.MemoryUse,BossMechanism.Field,BossPayload.Damage,"SeekerPurple",BossShape.Circle,BossAnchor.Hit,cooldownMillis:BossSeekerBalance.HandsA0CooldownMillis,delayMillis:BossSeekerBalance.HandsA0DelayMillis,lifetimeMillis:BossSeekerBalance.HandsA0LifetimeMillis,intervalMillis:BossSeekerBalance.HandsA0IntervalMillis,count:BossSeekerBalance.HandsA0Count,maxInstances:BossSeekerBalance.HandsA0MaxInstances,radiusMilli:BossSeekerBalance.HandsA0RadiusMilli,rangeMilli:BossSeekerBalance.HandsA0RangeMilli)),
            SeekerProfile("feet","強制移動や自動で生成された移動を除き、移動が終わったとき、移動前の位置に予告を出し、0.3秒後に半径1.5mの範囲へ攻撃力・魔力の高い方の22%（上限66%）の火属性ダメージを与える。ボスと行動妨害が効かない敵以外は、0.25秒間スタンする。再発動まで5秒かかる。","When you finish moving, excluding forced or automatically triggered movement, mark your departure point. After a 0.3-second warning, deal Fire damage equal to 22% of whichever is higher: your Attack or Ability Power (cap: 66%), in a 1.5m radius. Stun affected enemies for 0.25 seconds, except bosses and enemies immune to crowd control. Cooldown: 5 seconds.", "移动结束时（强制移动和自动触发的移动除外），在出发地点显示预警，0.3秒后对半径1.5m范围造成相当于攻击力与法术强度中较高一方22%（上限66%）的火属性伤害。除首领和免疫控制的敌人外，受影响的敌人眩晕0.25秒。冷却5秒。",new[]{SeekerChannel("SeekerFissure",BossSeekerBalance.SeekerFissureValue,BossSeekerBalance.SeekerFissureCap)},new BossAction(BossEvent.MovementCompleted,BossMechanism.Field,BossPayload.Damage,"SeekerFissure",cooldownMillis:BossSeekerBalance.FeetA0CooldownMillis,delayMillis:BossSeekerBalance.FeetA0DelayMillis,maxInstances:BossSeekerBalance.FeetA0MaxInstances,radiusMilli:BossSeekerBalance.FeetA0RadiusMilli,magnitudeMilli:BossSeekerBalance.FeetA0MagnitudeMilli,element:BossElement.Fire)),
            SeekerProfile("stage2","通常攻撃が命中したとき、現在の位相に応じた追加攻撃を行い、位相を緑、紫、赤の順に1段階進める。追加攻撃は攻撃力・魔力の高い方の16%のダメージで、再発動まで3秒かかる。位相は再発動待ちの間も命中ごとに進むが、1回の攻撃につき1段階までである。緑は8mを1秒で飛ぶ球、紫は対象地点に0.4秒の予告を出して半径1.5mへ攻撃、赤は同じ地点の半径1.5mへ火属性の即時攻撃である。","When your basic attack hits, make an additional attack based on your current phase, dealing damage equal to 16% of whichever is higher: your Attack or Ability Power. Cooldown: 3 seconds. Then advance one phase in the order green → purple → red. Hits advance the phase even during the cooldown, at most once per attack. Green fires an orb that travels 8m in 1 second. Purple strikes a 1.5m radius at the target point after a 0.4-second warning. Red immediately deals Fire damage in a 1.5m radius at that point.", "通常攻击命中时，根据当前相态发动追加攻击，造成相当于攻击力与法术强度中较高一方16%的伤害，冷却3秒。随后按绿→紫→红的顺序推进1个相态。冷却期间每次命中仍会推进相态，但每次攻击最多推进1次。绿色发射1秒内飞行8m的球；紫色在目标地点显示0.4秒预警后攻击半径1.5m范围；红色立即对同一地点半径1.5m范围造成火属性伤害。",new[]{SeekerChannel("SeekerPhase",BossSeekerBalance.SeekerPhaseValue,BossSeekerBalance.SeekerPhaseCap)},SeekerOrb(BossEvent.MainHit,"SeekerPhase",BossSeekerBalance.Stage2A0CooldownMillis),new BossAction(BossEvent.Clock,BossMechanism.Field,BossPayload.Damage,"SeekerPhase",BossShape.Circle,BossAnchor.Hit,delayMillis:BossSeekerBalance.Stage2A1DelayMillis,maxInstances:BossSeekerBalance.Stage2A1MaxInstances,radiusMilli:BossSeekerBalance.Stage2A1RadiusMilli,rangeMilli:BossSeekerBalance.Stage2A1RangeMilli),new BossAction(BossEvent.Clock,BossMechanism.ShapeAttack,BossPayload.Damage,"SeekerPhase",BossShape.Circle,BossAnchor.Hit,maxInstances:BossSeekerBalance.Stage2A2MaxInstances,radiusMilli:BossSeekerBalance.Stage2A2RadiusMilli,rangeMilli:BossSeekerBalance.Stage2A2RangeMilli,element:BossElement.Fire)),
            SeekerProfile("stage3","移動が終わったとき、移動前の位置に分身を1体、3秒間残す。再発動まで5秒かかり、防具効果の分身と合わせて同時に最大1体までで、召喚物としては扱わない。次の通常攻撃が命中したとき、分身の位置から主対象の地点（射程8m）へ現在の位相の攻撃を複製して、攻撃力・魔力の高い方の12%のダメージを与え、分身は消える。","When you finish moving, leave 1 double at your departure point for 3 seconds. Cooldown: 5 seconds. Only 1 double can exist at a time, including the armor effect's double, and it does not count as a summon. When your next basic attack hits, the double copies your current phase attack from its position toward the main target's position within an 8m range, dealing damage equal to 12% of whichever is higher: your Attack or Ability Power. The double then disappears.", "移动结束时，在出发地点留下1个分身，持续3秒，冷却5秒。与防具效果的分身合计同时最多存在1个，不视为召唤物。下一次通常攻击命中时，分身从自身位置向主要目标位置（射程8m）复制当前相态的攻击，造成相当于攻击力与法术强度中较高一方12%的伤害，随后分身消失。",new[]{SeekerChannel("SeekerEcho",BossSeekerBalance.SeekerEchoValue,BossSeekerBalance.SeekerEchoCap)},new BossAction(BossEvent.MovementCompleted,BossMechanism.Deployable,BossPayload.Deploy,"SeekerEcho",cooldownMillis:BossSeekerBalance.Stage3A0CooldownMillis,lifetimeMillis:BossSeekerBalance.Stage3A0LifetimeMillis,maxInstances:BossSeekerBalance.Stage3A0MaxInstances,rangeMilli:BossSeekerBalance.Stage3A0RangeMilli)),
            SeekerProfile("stage6","記憶を使ったとき、8m以内の敵の位置を狙い、0.5秒後、0.75秒後、1秒後に射程4m・角度90度の扇状の爪撃を放つ。爪撃はそれぞれ攻撃力・魔力の高い方の30%（合計90%、上限100%）のダメージを与える。さらに自身は攻撃力・魔力の高い方の38%（上限40%）の障壁を2.5秒間得る。再発動まで10秒かかる。発動中も操作でき、無敵にはならず、画面も暗転しない。","When you use a memory, aim at an enemy's position within 8m and unleash claw strikes after 0.5, 0.75, and 1 second. Each strike covers a 90-degree cone with a 4m range and deals damage equal to 30% of whichever is higher: your Attack or Ability Power (90% total; cap: 100%). Also gain a shield equal to 38% of whichever is higher: your Attack or Ability Power (cap: 40%), for 2.5 seconds. You can still act during this effect; it does not grant invulnerability or darken the screen. Cooldown: 10 seconds.", "使用记忆时，瞄准8m以内敌人的位置，分别于0.5秒后、0.75秒后和1秒后释放射程4m、角度90度的扇形爪击。每次造成相当于攻击力与法术强度中较高一方30%的伤害（合计90%，上限100%）。此外获得相当于攻击力与法术强度中较高一方38%（上限40%）的护盾，持续2.5秒。效果期间仍可操作，不会获得无敌，画面也不会变暗。冷却10秒。",new[]{SeekerChannel("SeekerClaws",BossSeekerBalance.SeekerClawsValue,BossSeekerBalance.SeekerClawsCap),SeekerChannel("SeekerClawGuard",BossSeekerBalance.SeekerClawGuardValue,BossSeekerBalance.SeekerClawGuardCap,BossCoefficientKind.Shield)},new BossAction(BossEvent.MemoryUse,BossMechanism.Field,BossPayload.Damage,"SeekerClaws",BossShape.Fan,BossAnchor.Hit,cooldownMillis:BossSeekerBalance.Stage6A0CooldownMillis,delayMillis:BossSeekerBalance.Stage6A0DelayMillis,intervalMillis:BossSeekerBalance.Stage6A0IntervalMillis,count:BossSeekerBalance.Stage6A0Count,maxInstances:BossSeekerBalance.Stage6A0MaxInstances,rangeMilli:BossSeekerBalance.Stage6A0RangeMilli,angleMilli:BossSeekerBalance.Stage6A0AngleMilli,magnitudeMilli:BossSeekerBalance.Stage6A0MagnitudeMilli),new BossAction(BossEvent.Clock,BossMechanism.Defense,BossPayload.Shield,"SeekerClawGuard",lifetimeMillis:BossSeekerBalance.Stage6A1LifetimeMillis,maxInstances:BossSeekerBalance.Stage6A1MaxInstances))
        };
        internal static BossRewardProfile[] CreateSeekerRewards()
        {
            BossRewardAction Heal()=>new BossRewardAction(BossRewardActionKind.NativeHeal,BossSeekerBalance.RewardHealValueMilli,BossSeekerBalance.RewardHealCapMilli,magnitudeMilli:BossSeekerBalance.RewardHealMagnitudeMilli);
            BossRewardAction Self()=>new BossRewardAction(BossRewardActionKind.NativeShield,BossSeekerBalance.RewardSelfValueMilli,BossSeekerBalance.RewardSelfCapMilli,durationMillis:BossSeekerBalance.RewardSelfDurationMillis,order:1,targetCapMilli:BossSeekerBalance.RewardSelfTargetCapMilli);
            return new[]{new BossRewardProfile(SeekerRewardId,SeekerSetId,"Gem_U_SoulPrison",BossRewardAdapter.SoulPrison,new[]{
                new BossRewardStage(1,new Txt("宝石「魂の牢獄」の救命効果が発動したとき、品質倍率をかけた後の最終回復量に、元の回復量の10%と、攻撃力・魔力の高い方の20%のうち低い方を上乗せする。別の回復が起きるわけではなく、HP1で耐える効果、元の超過回復、宝石の消費、無敵時間も変わらない。","When the Soul Prison gem's life-saving effect activates, increase its final healing after the quality multiplier by the lower of 10% of the original healing amount or 20% of whichever is higher: your Attack or Ability Power. This does not create a separate heal. Surviving at 1 HP, the original excess healing, gem consumption, and invulnerability duration remain unchanged.", "宝石“灵魂牢狱”的救命效果发动时，在品质倍率计算后的最终治疗量上，追加原有治疗量的10%与攻击力和法术强度中较高一方的20%中较低的数值。不会另行触发治疗。以1点HP存活、原有溢出治疗、宝石消耗和无敌时间均保持不变。"),new[]{Heal()}),
                new BossRewardStage(2,new Txt("固有報酬の段階1の効果に加え、「魂の牢獄」の救命回復の超過分の25%にあたる追加の障壁を、自身が6秒間得る。障壁の上限は攻撃力・魔力の高い方の30%である。元の超過回復と同量の無期限の障壁も、そのまま維持される。","In addition to boss reward stage 1, gain an extra shield equal to 25% of the excess healing from Soul Prison's life-saving effect, capped at 30% of whichever is higher: your Attack or Ability Power, for 6 seconds. The original shield, equal to the full excess healing amount and lasting indefinitely, is preserved.", "除首领专属奖励阶段1的效果外，获得相当于“灵魂牢狱”救命效果溢出治疗量25%的额外护盾，上限为攻击力与法术强度中较高一方的30%，持续6秒。原有等于全部溢出治疗量且永久持续的护盾保持不变。"),new[]{Heal(),Self()}),
                new BossRewardStage(3,new Txt("固有報酬の段階2の効果に加え、「魂の牢獄」の救命回復の超過分の25%にあたる障壁を、6m以内の最も近くにいる生存中の味方ヒーロー1人（自身を除く）に付与する。障壁の上限は攻撃力・魔力の高い方の40%、持続は3秒である。宝石が消費された後も効果時間の間は維持されるが、装備を外したとき、死亡したとき、部屋を移動したときには消える。無敵は延長されない。","In addition to boss reward stage 2, grant the nearest living allied hero within 6m, excluding yourself, a shield equal to 25% of the excess healing from Soul Prison's life-saving effect, capped at 40% of whichever is higher: your Attack or Ability Power, for 3 seconds. The shield lasts for its duration even after the gem is consumed, but disappears on unequipping, death, or changing rooms. Invulnerability duration is not extended.", "除首领专属奖励阶段2的效果外，为6m以内最近的1名存活友方英雄（自身除外）施加相当于“灵魂牢狱”救命效果溢出治疗量25%的护盾，上限为攻击力与法术强度中较高一方的40%，持续3秒。宝石消耗后，护盾仍会持续至时间结束，但在卸下装备、死亡或切换房间时消失。不会延长无敌时间。"),new[]{Heal(),Self(),new BossRewardAction(BossRewardActionKind.NativeShield,BossSeekerBalance.RewardAllyValueMilli,BossSeekerBalance.RewardAllyCapMilli,durationMillis:BossSeekerBalance.RewardAllyDurationMillis,rangeMilli:BossSeekerBalance.RewardAllyRangeMilli,order:2,targetCapMilli:BossSeekerBalance.RewardAllyTargetCapMilli)})})};
        }
        public static UniqueDef[] CreateSeekerPieces()=>new[]{
