            new UniqueDef("unique.boss_seeker.armor","armor.mirrorsilk_robe",new Txt("分身の外套","Double Mantle", "分身外套"),SeekerSetId,"boss_seeker.armor"),
            new UniqueDef("unique.boss_seeker.charm","charm.pulsing_core",new Txt("魂窓の珠","Soulwindow Pearl", "魂窗之珠"),SeekerSetId,"boss_seeker.charm"),
            new UniqueDef("unique.boss_seeker.head","head.moth_wing_mask",new Txt("狭界の面","Narrowworld Mask", "狭界之面"),SeekerSetId,"boss_seeker.head"),
